import { stitchSchemas } from '@graphql-tools/stitch';
import { buildSchema } from 'graphql';

const usersSchema = buildSchema(`
  type User {
    id: ID!
    name: String!
    email: String!
  }
  type Query {
    user(id: ID!): User
    users: [User!]!
  }
`);

const ordersSchema = buildSchema(`
  type Order {
    id: ID!
    userId: ID!
    total: Float!
    status: String!
  }
  type Query {
    order(id: ID!): Order
    ordersByUser(userId: ID!): [Order!]!
  }
`);

const gatewaySchema = stitchSchemas({
  subschemas: [
    { schema: usersSchema },
    { schema: ordersSchema }
  ],
  typeDefs: `
    extend type User {
      orders: [Order!]!
    }
  `,
  resolvers: {
    User: {
      orders: {
        selectionSet: '{ id }',
        resolve(user, _args, context, info) {
          return delegateToSchema({
            schema: ordersSchema,
            operation: 'query',
            fieldName: 'ordersByUser',
            args: { userId: user.id },
            context,
            info,
          });
        }
      }
    }
  }
});
